import{_ as s,C as r,c as n,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Leave types","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/setup/time-off-types.md","filePath":"master/human-resources/time-off/setup/time-off-types.md","lastUpdated":1791902625000}'),l={name:"master/human-resources/time-off/setup/time-off-types.md"};function d(f,e,p,g,h,m){const o=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="leave-types" tabindex="-1">Leave types <a class="header-anchor" href="#leave-types" aria-label="Permalink to &quot;Leave types&quot;">​</a></h1><p>A leave type is one kind of time off, such as <strong>Paid Time Off</strong> or <strong>Sick Time Off</strong>. It decides who must approve a request, whether the person needs days given first, and how the request is counted and coloured. Every request and every allocation uses a leave type.</p><blockquote><p><strong>In simple words:</strong> A leave type is a kind of leave with its own rules.</p></blockquote><p>Open <code>Time Off → Configuration → Leave Types</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Notified officers are users. Create them first in <a href="./../../../general-settings/users/manage-users.html">Manage users</a>. Seven leave types already exist, so you can start without creating one.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page lists every leave type. Two tabs sit above the list.</p><ul><li><strong>All:</strong> leave types in use.</li><li><strong>Archived:</strong> leave types you deleted. You can restore them here.</li></ul><p>The columns <strong>Name</strong> and <strong>Allocation Approval</strong> show by default. Use the columns icon (the toggle next to the search box) to add <strong>Time Off Approval</strong>, <strong>Notified Time Officers</strong>, <strong>Requires Allocation</strong>, <strong>Employee Request</strong>, <strong>Color</strong> and <strong>Company</strong>. Use the search box to find a type. The funnel icon opens the filters, where you can build rules on fields such as <strong>Name</strong>, <strong>Requires Allocation</strong> and <strong>Time Type</strong>.</p><p>Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. <strong>Delete</strong> archives the type.</p>',10)),a(o,{src:"/images1/time-off/to_set_types_list.png",alt:"Leave Types list with the All and Archived tabs, the Name and Allocation Approval columns and the seven leave types"}),e[1]||(e[1]=t('<h2 id="create-a-leave-type" tabindex="-1">Create a leave type <a class="header-anchor" href="#create-a-leave-type" aria-label="Permalink to &quot;Create a leave type&quot;">​</a></h2><p>This example creates a type for study leave.</p><ol><li>Open <code>Time Off → Configuration → Leave Types</code>.</li><li>Click <strong>New Leave Type</strong>. A full page opens.</li><li>Fill in the three cards, then click <strong>Create</strong>.</li></ol><h3 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to &quot;General Information&quot;">​</a></h3><ul><li><strong><em>Title:</em></strong> Required. The name people see, for example <code>Study Leave</code>.</li><li><strong><em>Approval:</em></strong> Who must approve a request. The default is <strong>By Time Off Officer</strong>.</li><li><strong><em>Requires Allocation:</em></strong> Choose <strong>Yes</strong> or <strong>No Limit</strong>. The default is <strong>No Limit</strong>.</li></ul><p><strong>Approval</strong> has four options.</p><ul><li><strong>No Validation</strong></li><li><strong>By Time Off Officer</strong></li><li><strong>By Employee&#39;s Approver</strong></li><li><strong>By Employee&#39;s Approver and Time Off Officer</strong></li></ul>',7)),a(o,{src:"/images1/time-off/to_set_type_general.png",alt:"General Information card of the Create Leave Type page with Title Study Leave and Requires Allocation set to No Limit"}),e[2]||(e[2]=t('<h4 id="what-requires-allocation-reveals" tabindex="-1">What Requires Allocation reveals <a class="header-anchor" href="#what-requires-allocation-reveals" aria-label="Permalink to &quot;What Requires Allocation reveals&quot;">​</a></h4><p>Choose <strong>Yes</strong>. Two more fields appear.</p><ul><li><strong><em>Employee Requests:</em></strong> <strong>Not Allowed</strong> (default) or <strong>Extra Days Request Allowed</strong>.</li><li><strong><em>Approval:</em></strong> A second <strong>Approval</strong> field, for allocations. Same four options. The default is <strong>By Time Off Officer</strong>. It shows in the list as <strong>Allocation Approval</strong>.</li></ul>',3)),a(o,{src:"/images1/time-off/to_set_type_yes.png",alt:"Create Leave Type page with Requires Allocation set to Yes showing Employee Requests and allocation Approval"}),e[3]||(e[3]=t('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The first <strong>Approval</strong> is for requests. The second is for allocations. They have the same label.</p></div><h3 id="display-option" tabindex="-1">Display Option <a class="header-anchor" href="#display-option" aria-label="Permalink to &quot;Display Option&quot;">​</a></h3><ul><li><strong><em>Color:</em></strong> Required. Empty by default. Type a hex code such as <code>#2f72cc</code>, or click the swatch dot and pick a colour in the panel. It paints the balance card and the calendar bars.</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><ul><li><strong><em>Notified Time Off Officers:</em></strong> Pick users from a searchable list. It is empty by default.</li><li><strong><em>Take Time Off In:</em></strong> How a request is counted. The default is <strong>Day</strong>. <strong>Half Day</strong> is also available.</li><li><strong><em>Public Holiday Included:</em></strong> Toggle, off by default.</li><li><strong><em>Allow to Attach Supporting Document:</em></strong> Toggle, off by default.</li><li><strong><em>Show on Dashboard:</em></strong> Toggle, off by default. When on, the type gets a balance card on <code>Time Off → My Time → Dashboard</code>.</li><li><strong><em>Kind of Time Off:</em></strong> <strong>Absence</strong> (default) or <strong>Worked Time</strong>.</li></ul><p>With <strong>Requires Allocation</strong> set to <strong>Yes</strong>, two more settings appear.</p><ul><li><strong><em>Allow Negative Cap:</em></strong> Toggle, off by default.</li><li><strong><em>Max Negative Cap:</em></strong> Required number, default <code>0</code>. It shows only when <strong>Allow Negative Cap</strong> is on.</li></ul>',7)),a(o,{src:"/images1/time-off/to_set_type_config.png",alt:"Display Option and Configuration cards with Color #2f72cc, Notified Time Off Officers HR Admin, Take Time Off In Day, only Show on Dashboard switched on and Kind of Time Off Absence"}),e[4]||(e[4]=t('<ol start="4"><li>Click <strong>Create</strong>. The type opens in the list. Use <strong>Create &amp; create another</strong> to add several.</li></ol><h2 id="the-seeded-leave-types" tabindex="-1">The seeded leave types <a class="header-anchor" href="#the-seeded-leave-types" aria-label="Permalink to &quot;The seeded leave types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Approval</th><th>Requires Allocation</th><th>Employee Requests</th><th>Allocation Approval</th><th>Public Holiday Included</th><th>Allow Negative Cap</th></tr></thead><tbody><tr><td><strong>Paid Time Off</strong></td><td>By Employee&#39;s Approver and Time Off Officer</td><td>Yes</td><td>Not Allowed</td><td>By Time Off Officer</td><td>On</td><td>Off</td></tr><tr><td><strong>Sick Time Off</strong></td><td>By Time Off Officer</td><td>No Limit</td><td></td><td></td><td>On</td><td></td></tr><tr><td><strong>Compensatory Days</strong></td><td>By Employee&#39;s Approver</td><td>No Limit</td><td></td><td></td><td>Off</td><td></td></tr><tr><td><strong>Unpaid</strong></td><td>By Employee&#39;s Approver and Time Off Officer</td><td>No Limit</td><td></td><td></td><td>Off</td><td></td></tr><tr><td><strong>Parental Leaves</strong></td><td>By Employee&#39;s Approver and Time Off Officer</td><td>Yes</td><td>Extra Days Request Allowed</td><td>By Employee&#39;s Approver and Time Off Officer</td><td>Off</td><td>Off</td></tr><tr><td><strong>Training Time Off</strong></td><td>By Employee&#39;s Approver and Time Off Officer</td><td>Yes</td><td>Not Allowed</td><td>By Time Off Officer</td><td>Off</td><td>On</td></tr><tr><td><strong>Extra Hours</strong></td><td>By Employee&#39;s Approver</td><td>No Limit</td><td></td><td></td><td>Off</td><td></td></tr></tbody></table><p>All seven have <strong>Show on Dashboard</strong> on and <strong>Kind of Time Off</strong> set to <strong>Absence</strong>.</p><h2 id="two-examples" tabindex="-1">Two examples <a class="header-anchor" href="#two-examples" aria-label="Permalink to &quot;Two examples&quot;">​</a></h2><p><strong>Paid Time Off</strong> needs an allocation. Priya Sharma has no days, so her request is refused until you allocate some. After you allocate 12 days, she can book up to 12.</p><p><strong>Sick Time Off</strong> has no day limit. Priya still needs an approved Sick Time Off allocation before Aureus accepts a request.</p><h2 id="edit-view-or-delete" tabindex="-1">Edit, view or delete <a class="header-anchor" href="#edit-view-or-delete" aria-label="Permalink to &quot;Edit, view or delete&quot;">​</a></h2><p>Click <strong>Edit</strong> to change any field, then <strong>Save changes</strong>. Click <strong>View</strong> for a read-only page. Click <strong>Delete</strong> to archive the type. Use <strong>Restore</strong> on the <strong>Archived</strong> tab to bring it back. A type that is in use cannot be deleted for good.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Setup</a></li><li><a href="./../allocations/">Allocations</a></li><li><a href="./../requests/request-time-off.html">Request time off</a></li><li><a href="./../../employees/employees/add-employee.html">Add an employee</a></li></ul>',11))])}const y=s(l,[["render",d]]);export{u as __pageData,y as default};
